 public:
  ProxyServer(uint16_t port) : acceptor_(io_context_, port) {}

  void run() {
    acceptor_.accept(boost::bind(&ProxyServer::handle_accept, this, _1));
  }

 private:
  void handle_accept(boost::shared_ptr<boost::asio::ip::tcp::socket> socket) {
    // ... (Handle client connection)
    // Create a worker thread for asynchronous processing.
    std::thread worker([this, socket]() {
      process_request(socket);
