    public DatabaseExecutor(string connectionString)
    {
        _connectionString = connectionString;
        _connectionPool = new SqlConnectionPool(_connectionString);
    }

    public async Task<string> ExecuteQueryAsync(string sqlCommand, List<SqlParameter> parameters, int timeoutMilliseconds)
    {
        if (await ValidateAndInitializeConnection(sqlCommand, timeoutMilliseconds))
        {
            using (var connection = await _connectionPool.GetConnectionAsync())
            {
                try
                {
                    using (var command = new SqlCommand(sqlCommand, connection))
                    {
                        command.Parameters.AddRange(parameters.ToArray());
                        return await command.ExecuteScalarAsync();
                    }
                }
                catch (Exception ex)
                {
                    // Handle exceptions gracefully with logging and retry logic
                    Console.WriteLine($"Error executing query: {ex.Message}");
                    throw; 
