        this.storageEndpoint = storageEndpoint;
        this.authEndpoint = authEndpoint;
        this.updateBucket = Bucket4j.builder()
                .build();
        this.deleteBucket = Bucket4j.builder()
                .build();
    }

    public Resource updateResource(String resourceId, ResourcePayload payload) {
        // Authentication logic using the authEndpoint and payload
        // Validation against predefined schemas and business rules
        updateBucket.tryConsumeAndReturnRemainingAmount((amount) -> {
            if (amount > 0) {
                try {
                    // Update resource in external storage using the storageEndpoint
                    Resource updatedResource = updateStorage(resourceId, payload);

                    // Generate MD5 hash for the updated resource
                    String md5Hash = generateMD5Hash(updatedResource);

                    return updatedResource;
                } catch (Exception e) {
                    // Handle potential network latency and transient errors
                    logger.error("Error updating resource: ", e);
                    return null; // Or handle appropriately
                }
            } else {
                // Retry logic for update bucket exhaustion
                updateBucket.tryConsume(1, TimeUnit.SECONDS);
                return null;
            }
        });
    }

    public Confirmation deleteResource(String resourceId) {
        deleteBucket.tryConsumeAndReturnRemainingAmount((amount) -> {
            if (amount > 0) {
                try {
                    // Delete resource from external storage using the storageEndpoint
                    deleteStorage(resourceId);
                    return new Confirmation(resourceId, generateDefaultMD5Hash());
                } catch (Exception e) {
                    // Handle potential network latency and transient errors
                    logger.error("Error deleting resource: ", e);
                    return null; // Or handle appropriately
                }
            } else {
                // Retry logic for delete bucket exhaustion
                deleteBucket.tryConsume(1, TimeUnit.SECONDS);
                return null; 
