async function runTests(moduleName, testCases, blueslipMock) {
  const module = require(moduleName);

  for (const testCase of testCases) {
    blueslipMock.reset();

    try {
      console.log(`[START] ${moduleName}:${testCase.label}:${JSON.stringify(testCase.metadata)}`);
      const startTime = Date.now();
      await Promise.race([
        testCase.testFunction(),
        new Promise((_, reject) => setTimeout(reject, testCase.timeout || 500)),
      ]);
      const endTime = Date.now();
      console.log(`[END] ${moduleName}:${testCase.label}:${JSON.stringify(testCase.metadata)} - Duration: ${endTime - startTime}ms`);
    } catch (error) {
      console.error(`[ERROR] ${moduleName}:${testCase.label}:${JSON.stringify(testCase.metadata)} - Error: ${error}`);
      // Implement detailed error logging and reporting
    }
  }
}
