  controller: function($scope, $http, $q) {
    var ctrl = this;

    // Cache for fetched data
    this.dataCache = {};

    // Regular expression for Old Testament book names
    const oldTestamentBookRegex = /\b(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)\b/i;

    // Function to fetch data from API
    this.fetchData = function(fieldName) {
      return $q((resolve, reject) => {
        if (ctrl.dataCache[fieldName]) {
          resolve(ctrl.dataCache[fieldName]);
          return;
        }
        $http.get(`api/data/${fieldName}`)
          .then(response => {
            ctrl.dataCache[fieldName] = response.data;
            resolve(response.data);
          })
          .catch(error => {
            console.error('API Error:', error); 
            reject({ message: 'Failed to fetch data' });
          });
      });
    };

    // Function to validate input against regex
    this.validateInput = function(input) {
      const matches = oldTestamentBookRegex.exec(input.toLowerCase());
      return matches ? matches[0] : null; 
    };

    // Watch for changes in fieldNames from parent
    $scope.$watch('ctrl.fieldNames', (newFields, oldFields) => {
      // Update fields asynchronously
      for (let fieldName of newFields) {
        this.fetchData(fieldName).then(data => {
          $scope[fieldName] = data; // Assign to scope for view update
          this.onFieldUpdated({ field: fieldName, value: data }); 
        });
      }
    }, true); 
  }
});

