    redis_client = StrictRedis(host='localhost', port=6379, db=0)
    redis_client.set(key, value, ex=ttl)

# ... (Implement dynamic load balancing logic for Redis) ...

def get_data(key):
    cached_value = redis_client.get(key)
    if cached_value:
        return cached_value.decode('utf-8') 
    else:
        result = fetch_data.delay(key)
        if result.successful():
            cached_value = result.get()
            cache_data.delay(key, cached_value)  
        else:
            logger.warning(f"Failed to retrieve data from external API for key {key}") 
        return cached_value


