<?php

// ... (Semaphore initialization and cleanup functions in C)

function updateClinicStatus($clinicId, $status, $ipAddress) {
  $semaphore = initializeSemaphore(); // Initialize semaphore
  if ($semaphore === false) {
    error_log("Failed to initialize semaphore.");
    return false;
  }

  // Acquire semaphore lock
  if (acquireSemaphore($semaphore) === false) {
    error_log("Failed to acquire semaphore lock.");
    destroySemaphore($semaphore); // Release semaphore on failure
    return false;
  }

  try {
    $conn = getDatabaseConnection(); 
    $stmt = $conn->prepare("UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = NOW() WHERE id = ?");
    $stmt->bind_param("sss", $status, $ipAddress, $clinicId);

    if ($stmt->execute() === false) {
      error_log("Failed to update clinic status: " . $conn->error);
      throw new Exception("Database error.");
    } 

    // Release semaphore lock
    releaseSemaphore($semaphore); 
  } catch (Exception $e) {
    error_log("Error updating clinic status: " . $e->getMessage());
    destroySemaphore($semaphore); // Release semaphore on exception
    return false;
  } finally {
    $stmt->close();
    // Close database connection
  }

  return true;
} 


?>
```



