    private readonly string _key;
    private readonly string _iv;

    public SecureDataProcessor(string key, string iv)
    {
        _key = key;
        _iv = iv;
    }

    public async Task<T> ProcessEncryptedFile<T>(string filePath) where T : class 
    {
        try
        {
            using (var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
            {
                byte[] encryptedData = await ReadFullyAsync(fileStream);

                using (var aes = Aes.Create())
                {
                    aes.Key = Encoding.UTF8.GetBytes(_key);
                    aes.IV = Encoding.UTF8.GetBytes(_iv);

                    using (var decryptor = aes.CreateDecryptor())
                    {
                        byte[] decryptedData = decryptor.TransformFinalBlock(encryptedData, 0, encryptedData.Length);

                        return Deserialize<T>(decryptedData);
                    }
                }
            }
        }
        catch (Exception ex)
        {
            // Log error details for debugging
            Console.WriteLine($"Error processing file: {ex.Message}");
            throw; 
        }
    }

    private async Task<byte[]> ReadFullyAsync(Stream stream)
    {
        using (var memoryStream = new MemoryStream())
        {
            await stream.CopyToAsync(memoryStream);
            return memoryStream.ToArray();
        }
    }

    private T Deserialize<T>(byte[] data) where T : class
