async function runTests(moduleName, testCases, blueslipMock, externalDependencies) {
  const module = require(moduleName);

  for (const testCase of testCases) {
    blueslipMock.reset(); 

    console.log(`[START] ${moduleName}:${testCase.label}:${JSON.stringify(testCase.metadata)}`);
    try {
      await new Promise((resolve, reject) => {
        const timeoutId = setTimeout(() => {
          reject(new Error(`Timeout: Test '${testCase.label}' exceeded 500ms`));
        }, testCase.timeout || 500);

        testCase.testFunction()
          .then(resolve)
          .catch(reject);
      });
    } catch (error) {
      console.error(`[END] ${moduleName}:${testCase.label}:${JSON.stringify(testCase.metadata)} - FAILED:`, error); 
    } finally {
      console.log(`[END] ${moduleName}:${testCase.label}:${JSON.stringify(testCase.metadata)}`);
    }
  }
}
