    {
        _configuration = configuration;
        _processorFactory = new DataProcessorFactory(_configuration);
        _serviceBusClient = new ServiceBusClient(_configuration["ServiceBusConnectionString"]);
    }

    public async Task ProcessDataAsync()
    {
        var consumer = _serviceBusClient.CreateReceiver(
            _configuration["QueueName"], 
            new ServiceBusReceiveOptions { MessageHandlerOptions = new MessageHandlerOptions<byte[]>() });

        await foreach (var message in consumer.ReceiveMessagesAsync())
        {
            try
            {
                // Secure transmission and validation of byte arrays here...
                var dataProcessor = _processorFactory.CreateProcessor(message.Body, message.SystemProperties);

                // Data transformation/enrichment based on configuration
                await dataProcessor.ProcessAsync();

                consumer.CompleteMessage(message); // Signal successful processing
            }
            catch (Exception ex) 
            {
                // Robust error handling and logging here...
                _serviceBusClient.DeadLetterMessage(message, "ErrorProcessing", ex.Message);
            }
        }
    }

}


