# JSONSerializableBase.py
class JSONSerializable:
    def to_json(self):
        raise NotImplementedError

    @classmethod
    def from_json(cls, json_data):
        raise NotImplementedError

# ClassRegistry.py
class ClassRegistry:
    def __init__(self, metadata_service):
        self._metadata_service = metadata_service
        self._factories = {}
        self._refresh_registry()

    def _refresh_registry(self):
        for factory_data in self._metadata_service.get_factories():
            factory_id = factory_data['id']
            factory_class = factory_data['class']
            setattr(self, f'_factory_{factory_id}', type(
                'Factory_' + factory_id, (object,), {
                    '__call__': lambda self: factory_class().to_json()
                }
            ))
        # Handle removals and updates here

    def get_factory(self, factory_id):
        if factory_id in self._factories:
            return getattr(self, f'_factory_{factory_id}')
        else:
            raise ValueError(f"Unknown factory ID: {factory_id}")

# Example Usage.py

class Person(JSONSerializable):
    def __init__(self, name, age):
        self.name = name
        self.age = age

    def to_json(self):
        return json.dumps({'name': self.name, 'age': self.age})

    @classmethod
    def from_json(cls, json_data):
        data = json.loads(json_data)
        return cls(data['name'], data['age'])

# Initialize the registry with metadata service
registry = ClassRegistry(MetadataService())  

# Example deserialization
json_str = '{"name": "John", "age": 30}'
