import threading
import time  
from collections import defaultdict

class Metric:
    def __init__(self, name, type):
        self.name = name
        self.type = type
        self.value = None 

    def update(self, value):
        self.value = value

class MetricsCollector:
    def __init__(self):
        self.metrics = defaultdict(lambda: Metric(None, None))  
        self.lock = threading.Lock() 

    def register_metric(self, name, metric_type):
        with self.lock:
            if name not in self.metrics:
                self.metrics[name] = Metric(name, metric_type)

    def update_metric(self, name, value):
        with self.lock:
            self.metrics[name].update(value)

    def get_metrics(self):
        with self.lock:
            return {metric.name: metric.value for metric in self.metrics.values()}

# Example Usage 
collector = MetricsCollector()
collector.register_metric("counter", "counter")
collector.register_metric("gauge", "gauge")

while True:
    collector.update_metric("counter", collector.get_metrics().get("counter", 0) + 1)  
    time.sleep(1)



```




