// DynamicFileUploaderService.cs

using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;

public interface IStorageProvider 
{
    Task UploadFileAsync(string fileName, byte[] content);
}

public class S3StorageProvider : IStorageProvider { ... } // Implement AWS S3 functionality

public class AzureBlobStorageProvider : IStorageProvider { ... } // Implement Azure Blob Storage functionality

public class DynamicFileUploaderService 
{
    private readonly IConfiguration _configuration;
    private Dictionary<string, Type> _storageProviders = new();

    public DynamicFileUploaderService(IConfiguration configuration)
    {
        _configuration = configuration;
        RegisterStorageProvider("s3", typeof(S3StorageProvider)); // Example: Register AWS S3 provider
        RegisterStorageProvider("azureblob", typeof(AzureBlobStorageProvider)); // Example: Register Azure Blob Storage provider
    }

    public async Task UploadFileAsync(string fileName, byte[] content, string storageType = "s3")
    {
        if (!_storageProviders.ContainsKey(storageType))
        {
            throw new ArgumentException($"Unknown storage type: {storageType}");
        }

        var providerType = _storageProviders[storageType];
        var provider = (IStorageProvider)Activator.CreateInstance(providerType); // Dynamically create the provider instance
        await provider.UploadFileAsync(fileName, content);
    }

    private void RegisterStorageProvider(string name, Type providerType) 
    { 
        _storageProviders[name] = providerType; 
    }
}
