#include <thread>
#include <mutex>
#include <condition_variable>

namespace DynamicDataPipeline {

  class Source {
    public:
      virtual ~Source() = default;
      virtual std::string readData() = 0; // Abstract method for reading data from source
  };

  class Processor {
    public:
      virtual ~Processor() = default;
      virtual void process(const std::string& data) = 0; // Abstract method for processing data
  };

  class Sink {
    public:
      virtual ~Sink() = default;
      virtual void writeData(const std::string& data) = 0; // Abstract method for writing processed data
  };

  class Pipeline {
    private:
      std::unique_ptr<Source> source_;
      std::unique_ptr<Processor> processor_;
      std::unique_ptr<Sink> sink_;
      std::mutex mutex_;
      std::condition_variable cv_;

    public:
      Pipeline(std::unique_ptr<Source> source, std::unique_ptr<Processor> processor, 
               std::unique_ptr<Sink> sink) : source_(std::move(source)), processor_(std::move(processor)), 
                                             sink_(std::move(sink)) {}

      void run() {
        while (true) {
          {
            std::lock_guard<std::mutex> lock(mutex_);
            auto data = source_->readData();
            if (!data.empty()) {
              processor_->process(data);
              sink_->writeData(data);
            }
          }
          cv_.wait(lock); // Wait for a signal to continue processing
        }
      }
  };

} 

int main() {
  // Instantiate sources, processors, and sinks 
  auto source = std::make_unique<HttpApiSource>(); 
  auto processor = std::make_unique<JsonProcessor>();
  auto sink = std::make_unique<FileSink>(); 

  // Create a pipeline instance
  DynamicDataPipeline::Pipeline pipeline(std::move(source), std::move(processor), std::move(sink));

  // Start the pipeline processing loop in a separate thread
  std::thread workerThread(&DynamicDataPipeline::Pipeline::run, &pipeline);

  // ... Rest of your application logic 
  workerThread.join();

  return 0;
}



