char* truncate_and_append(const char* str, size_t size_limit) {
  size_t str_len = strlen(str);

  if (str_len <= size_limit) {
    char *new_str = malloc(str_len + 2); // Allocate memory for the new string with slash
    strcpy(new_str, str);             // Copy the original string
    new_str[str_len] = '/';            // Append a slash
    new_str[str_len + 1] = '\0';      // Null-terminate the new string
