        _userAnalyticsCollection = userAnalyticsCollection;
        _redisCache = redisCache;
        _metadataService = metadataService;
        _distributedLock = distributedLock; 
    }

    [HttpPost("/analytics")]
    public async Task<IActionResult> ProcessAnalytics([FromBody] UserInteractionDto interaction)
    {
        if (!ModelState.IsValid)
        {
            // Log errors and reject invalid requests
            return BadRequest(); 
        }

        var userId = interaction.UserId;

        await _distributedLock.AcquireAsync(userId); // Acquire lock for user

        try 
        {
            var userExists = await _metadataService.UserExistsAsync(userId);
            if (!userExists)
            {
                // Log warning and reject request
                return BadRequest("User not found.");
            }

            // Process interaction logic...

            await _publishEndpoint.Publish(new AnalyticsEvent { UserId = userId, ... }); // Publish event

            var analyticsData = new UserAnalytics { 
                UserId = userId, 
                InteractionType = interaction.Type,
                // ... other properties
            };
            _userAnalyticsCollection.InsertOneAsync(analyticsData);  
        }
        finally
        {
            _distributedLock.Release(userId); // Release lock
        }

        return Ok();
    } 

}


