public async Task<Stream> ProcessLogDataAsync(string queueName)
{
    var logConsumer = new LogMessageConsumer(queueName);

    var tasks = new List<Task>();

    await foreach (var logMessage in logConsumer.ReceiveMessages())
    {
        tasks.Add(ProcessLogAsync(logMessage));
    }

    await Task.WhenAll(tasks);

    // Process and report any errors encountered during processing
    if (errors.Any())
    {
        return new MemoryStream(Encoding.UTF8.GetBytes("Error: " + string.Join("\n", errors)));
    }

    return processedDataStream; 
}


private async Task ProcessLogAsync(string logMessage)
{
    try
    {
        // Parse and process the log message
        var processedData = ProcessLogContent(logMessage);
        processedDataStream.Write(processedData); // Add processed data to stream

    }
    catch (Exception ex)
    {
        errors.Add($"Error processing log message: {ex.Message}");
    }
} 


```  



