import threading
from typing import Dict, Callable, Any

class ClassRegistry(object):
    _instance = None
    _lock = threading.Lock()
    def __new__(cls, *args, **kwargs):
        if not cls._instance:
            with cls._lock:
                if not cls._instance:
                    cls._instance = super(ClassRegistry, cls).__new__(cls)
                    cls._instance._registry = {}  
        return cls._instance

    def register_class(self, factory_id: str, factory_function: Callable):
        self._registry[factory_id] = factory_function

    def get_class_by_id(self, factory_id: str) -> Callable:
