    {
        _gatewayFactory = gatewayFactory;
        _transactionBatcher = transactionBatcher;
    }

    // Public method to process a payment
    public async Task<TransactionResult> ProcessPaymentAsync(PaymentRequest request)
    {
        // Determine appropriate gateway based on request parameters (currency, etc.)
        var gateway = _gatewayFactory.CreateGateway(request.Currency);

        // Batch transactions for efficiency
        var batch = _transactionBatcher.GetBatch(request.Currency);
        batch.Add(request);

        if (batch.IsFull())
        {
            await gateway.ProcessBatchAsync(batch); 
        }

        // ... Handle real-time event triggering, background processing, etc.
    }
}


