    long offset;
} Record;

typedef struct {
    Record* records;
    size_t size;
    pthread_mutex_t mutex; 
} DynamicRecordsCollection;

// Function to initialize a DynamicRecordsCollection
DynamicRecordsCollection* initDynamicRecordsCollection(size_t initialSize) {
    DynamicRecordsCollection* collection = (DynamicRecordsCollection*)malloc(sizeof(DynamicRecordsCollection));
    collection->records = (Record*)calloc(initialSize, sizeof(Record)); 
    collection->size = initialSize;
    pthread_mutex_init(&collection->mutex, NULL); 
    return collection;
}

// Function to safely add a Record to the collection in a thread-safe manner
void addRecord(DynamicRecordsCollection* collection, int key, long offset) {
    pthread_mutex_lock(&collection->mutex);
    // Implement logic to handle adding new records and resizing the array if needed
    pthread_mutex_unlock(&collection->mutex); 
}

```




