#include <iostream>
#include <random>

class RandomValueGenerator {
private:
    double min_;
    double max_;

public:
    RandomValueGenerator(double min, double max) : min_(min), max_(max) {}

    double getRandomFloat() {
        std::random_device rd;  // Obtain a seed for the random number generator.
        std::mt19937 generator(rd()); // Create a Mersenne Twister engine seeded with rd().
        std::uniform_real_distribution<> distribution(min_, max_);
        return distribution(generator);
    }

    int getRandomInt() {
        std::random_device rd;  // Obtain a seed for the random number generator.
        std::mt19937 generator(rd()); // Create a Mersenne Twister engine seeded with rd().
        std::uniform_int_distribution<> distribution(static_cast<int>(min_), static_cast<int>(max_)); 
        return distribution(generator);
    }

    friend std::ostream& operator<<(std::ostream& os, const RandomValueGenerator& generator) {
        os << "Range: [" << generator.min_ << ", " << generator.max_ << "]";
        return os;
    }
};



