        this.typeDataAPI = typeDataAPI;
        this.translationService = translationService;
        this.loggingService = loggingService;
        this.cacheManager = cacheManager;
        this.serviceDiscovery = serviceDiscovery;
    }

    @GET("/pokemon/{name}")
    public PokemonDetails getPokemonDetails(@PathVariable String name) {
        String cachedData = cacheManager.get(name);
        if (cachedData != null) {
            return JSONUtils.fromJson(cachedData, PokemonDetails.class);
        }

        // Fetch data from external APIs and translate
        Type type = typeDataAPI.getTypeByName(name);
        String weaknessText = translationService.translate(type.getWeaknesses()); 
        String resistanceText = translationService.translate(type.getResistances());
        String immunityText = translationService.translate(type.getImmunities());

        PokemonDetails details = new PokemonDetails(name, weaknessText, resistanceText, immunityText);
        cacheManager.put(name, JSONUtils.toJson(details));
        return details; 
    }

    // ... Additional methods for handling errors, logging, etc.  ...
}
