// ... API Gateway Implementation ...

public static string DecryptMessage(string base64EncryptedMessage, string key, string iv)
{
    // 1. Convert Base64 to Byte Array
    byte[] encryptedBytes = Convert.FromBase64String(base64EncryptedMessage);

    // 2. Create TripleDESCryptoServiceProvider object
    using (TripleDESCryptoServiceProvider tdes = new TripleDESCryptoServiceProvider())
    {
        tdes.Key = ASCIIEncoding.ASCII.GetBytes(key); 
        tdes.IV = ASCIIEncoding.ASCII.GetBytes(iv);

        // 3. Create Decryptor
        ICryptoTransform decryptor = tdes.CreateDecryptor();

        // 4. Decrypt the Message
        using (MemoryStream msDecrypt = new MemoryStream(encryptedBytes))
        {
            using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
            {
                using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                {
                    return srDecrypt.ReadToEnd();
                }
            }
        }
    }
} 

// ... Rest of API Gateway Implementation ...
```



**Explanation:**

* **Triple DES Encryption:** This code utilizes the TripleDES algorithm for encryption, which is considered a strong symmetric encryption method.
* **Key and Initialization Vector (IV):** You must provide a valid `key` and `iv` when calling the `DecryptMessage` function. 
