typedef struct {
  int value;
  pthread_mutex_t mutex;
  pthread_cond_t cond;
} Semaphore;

Semaphore *semaphores = NULL;
int semaphoreCount = 0;
int maxSemaphores = 10000; 

void initSemaphorSystem(int numServers) {
  // ... (Initialize message queue, logging framework, etc.)
  semaphores = malloc(maxSemaphores * sizeof(Semaphore));
  // ... (Implement server discovery and load balancing logic)
}

Semaphore *createSemaphore(const char *name, int initialValue) {
  // ... (Acquire lock on semaphore array, check for duplicate names)
  if (semaphoreCount >= maxSemaphores) {
    fprintf(stderr, "Error: Maximum number of semaphores reached.\n");
    return NULL;
  }

  Semaphore *sem = &semaphores[semaphoreCount];
  sem->value = initialValue;
  pthread_mutex_init(&sem->mutex, NULL);
  pthread_cond_init(&sem->cond, NULL);
  semaphoreCount++;
  // ... (Log semaphore creation)

  return sem; 
}

void wait(Semaphore *sem) {
  pthread_mutex_lock(&sem->mutex);
  while (sem->value <= 0) {
    pthread_cond_wait(&sem->cond, &sem->mutex);
  }
  sem->value--;
  pthread_mutex_unlock(&sem->mutex);
}

void signal(Semaphore *sem) {
  pthread_mutex_lock(&sem->mutex);
  sem->value++;
  pthread_cond_signal(&sem->cond);
  pthread_mutex_unlock(&sem->mutex);
}

void destroySemaphore(Semaphore *sem) {
  // ... (Acquire lock on semaphore array, decrement count)
  pthread_mutex_destroy(&sem->mutex);
  pthread_cond_destroy(&sem->cond);
  semaphoreCount--;
  // ... (Log semaphore destruction)
}

// ... (Implement unit tests for all functions) 


