async function executeTestSuite(moduleName, testCases, integrationMocks) {
  const module = require(moduleName); 

  for (const testCase of testCases) {
    try {
      // Reset integration mocks for each test case
      Object.assign(global, integrationMocks); // Overwrite global mocks

      const startTime = Date.now();
      await new Promise((resolve, reject) => {
        testCase.testFunction()
          .then(result => {
            const endTime = Date.now();
            console.log(`Test '${testCase.label}' passed in ${endTime - startTime}ms`, result); 
            resolve();
          })
          .catch(error => {
            const endTime = Date.now();
            console.error(`Test '${testCase.label}' failed in ${endTime - startTime}ms`, error);
            reject(error);
          });
      })
        .timeout(testCase.timeout || 1000); // Timeout handling

    } catch (error) {
      // Error handling: Catch unhandled rejections and exceptions
      console.error(`Uncaught error during test '${testCase.label}'`, error);
    }
  }
}


