@ConfigMapping(prefix = "oauth2")
public class OAuth2TokenValidatorConfig {

    private String schemaRegistryUrl;
    private int maxConcurrentRequests;
    private int degradationThreshold;

    // ... getters and setters
}


public class OAuth2TokenValidator {

    private final Map<String, OAuth2ProviderSchema> providerSchemas;
    private final SchemaRegistryClient schemaRegistryClient;
    private final MetricsTracker metricsTracker;

    public OAuth2TokenValidator(OAuth2TokenValidatorConfig config) {
        this.providerSchemas = new ConcurrentHashMap<>();
        this.schemaRegistryClient = new SchemaRegistryClient(config.getSchemaRegistryUrl());
        this.metricsTracker = new MetricsTracker();
    }

    public boolean validateToken(String tokenJson) {
        try {
            OAuth2TokenRequest request = objectMapper.readValue(tokenJson, OAuth2TokenRequest.class);
            OAuth2ProviderSchema schema = providerSchemas.getOrDefault(request.getProvider(), defaultSchema()); 

            // Validate using the schema 
            schema.validate(request);

            return true; 

        } catch (IOException e) {
            metricsTracker.trackDeserializationError();
            throw new RuntimeException("Failed to deserialize token request", e); 
        } 
    }

    private OAuth2ProviderSchema defaultSchema() {
        // Default schema implementation 
        return new SimpleOAuth2ProviderSchema();
    }



    public void registerProvider(String providerId, Schema schema) {
        providerSchemas.put(providerId, schema);
    }


}







```

