using System;
using System.Collections.Generic;
using System.Threading.Tasks;

namespace RealtimeLogProcessor
{
    public class LogDataProcessor
    {
        private readonly ILogQueue _logQueue;
        private readonly ILogProcessorFactory _processorFactory;
        private readonly IDatabaseWriter _databaseWriter;

        public LogDataProcessor(ILogQueue logQueue, ILogProcessorFactory processorFactory, IDatabaseWriter databaseWriter)
        {
            _logQueue = logQueue;
            _processorFactory = processorFactory;
            _databaseWriter = databaseWriter;
        }

        public async Task ProcessLogsAsync()
        {
            while (true)
            {
                var logs = await _logQueue.DequeueBatchAsync();

                foreach (var log in logs)
                {
                    // Create a processor based on the log type
                    var processor = _processorFactory.CreateProcessor(log);

                    // Process the log asynchronously
                    await Task.Run(() =>
                    {
                        var processedData = processor.Process(log);
                        _databaseWriter.WriteLogData(processedData); 
                    });
                }

                // Introduce a delay to avoid overloading the system
                await Task.Delay(TimeSpan.FromMilliseconds(10));
            }
        }
    }
}
