import csv
import json

def process_transactions(filename):
    data = []
    with open(filename, 'r') as file:
        reader = csv.DictReader(file)
        for row in reader:
            # Data validation and transformation
            try:
                amount = float(row['Amount'])
                date = row['Date']  
                data.append({'Amount': amount, 'Date': date})
            except ValueError as e:
                print(f"Error processing row: {row}, Reason: {e}")

    # Aggregate and generate report
    total_amount = sum([item['Amount'] for item in data])
    report = {
        'Total Transactions': len(data),
        'Total Amount': total_amount
    }
    with open('transaction_report.json', 'w') as outfile:
        json.dump(report, outfile)

if __name__ == "__main__":
    process_transactions('transactions.csv') 
```




