class UserDao {

    private $dbConnection;

    public function updatePassword($userId, $newPassword) {
        // Validate password strength
        if (!preg_match("/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[\W]).{8,}$/", $newPassword)) {
            throw new Exception("Password must be at least 8 characters long and include lowercase, uppercase, a number, and a special character.");
        }

        // Sanitize input 
        $userId = mysqli_real_escape_string($this->dbConnection, $userId);
        $newPassword = password_hash($newPassword, PASSWORD_DEFAULT);

        $sql = "UPDATE users SET password = '$newPassword' WHERE id = $userId";
        if (mysqli_query($this->dbConnection, $sql)) {
            return true; // Password updated successfully
        } else {
            throw new Exception("Error updating password: " . mysqli_error($this->dbConnection));
        }
    }

    // ... other DAO methods 
}
