import java.io.*;

public class SafeDeserializer {

    public static <T> T deserialize(byte[] data, Class<T> clazz) {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(data); 
             ObjectInputStream ois = new ObjectInputStream(bais)) {
            return (T) ois.readObject();
        } catch (ClassNotFoundException e) {
            log.error("Class not found during deserialization", e);
            throw new RuntimeException("Unable to deserialize object: Class Not Found", e);
        } catch (IOException e) {
            log.error("Error during deserialization", e);
            throw new RuntimeException("Unable to deserialize object", e);
        }
    }

}
```


