import reqwest::blocking;
use reqwest::{ClientBuilder, StatusCode};

pub fn create_http_client(insecure: bool, proxy: Option<&str>) -> Result<reqwest::blocking::Client, String> {
    let mut builder = ClientBuilder::new();
    if let Some(proxy) = proxy {
        builder = builder.proxy(reqwest::Proxy::http(proxy));
    }

    if insecure {
        builder = builder.danger_accept_invalid_certs();
    }

    Ok(builder.build()?)
}


