        .stdout(Stdio::null())
        .stderr(Stdio::inherit())
        .spawn()
        .map_err(|e| format!("Failed to spawn rustc process: {}", e))?;

    // Implement your custom logging hook here

    let exit_code = catch_with_exit_code(&mut child)?;
    let duration = start.elapsed();

    println!("Compilation finished with exit code: {}", exit_code);
    println!("Compilation time: {:?}", duration);

    Ok(exit_code)
}

fn main() {
    if let Err(e) = compile_rust_with_logging() {
        eprintln!("Error during compilation: {}", e);
    }
}
```



