function refreshDialogFields(resource_id, url) {
  // Get dialog field names to refresh
  const fieldNamesToRefresh = ['field1', 'field2', 'field3']; // Replace with actual field names

  // Iterate through all dialog fields
  angular.forEach(document.querySelectorAll('#dialog-form input'), function (inputField) {
    // Check if the field name matches any of the names to refresh
    if (fieldNamesToRefresh.includes(inputField.name)) {
      // Send message to parent window with field name and resource ID
      window.parent.postMessage({ fieldName: inputField.name, resourceId: resource_id }, '*');

      // Listen for response from parent window
      window.addEventListener('message', function (event) {
        if (event.data.fieldName === inputField.name) {
          inputField.value = event.data.result; // Update field value with result
        }
      });
    }
  });
}

