// Thread-Safe File Operations code
import java.io.File;
import java.util.concurrent.locks.ReentrantLock;


public class FileManager {
    private static final ReentrantLock LOCK = new ReentrantLock();
    private static volatile long lastSuccessfulDeletionTime = 0L;

    public static void deleteDataFile(String filePath) {
        LOCK.lock();
        try {
            File file = new File(filePath);
            if (file.exists()) {
                file.delete();
                lastSuccessfulDeletionTime = System.currentTimeMillis();
            }
        } finally {
            LOCK.unlock();
        }
    }

    // ... other methods for managing thread-safe file operations


}



