public class DynamicSecureDataPipeline 
{
    private readonly IKeyManagementService _kms;
    private readonly ISecurityPolicyManager _securityPolicyManager;
    private readonly IMicroserviceRegistry _microserviceRegistry;

    public DynamicSecureDataPipeline(IKeyManagementService kms, 
                                     ISecurityPolicyManager securityPolicyManager,
                                     IMicroserviceRegistry microserviceRegistry)
    {
        _kms = kms;
        _securityPolicyManager = securityPolicyManager;
        _microserviceRegistry = microserviceRegistry;
    }

    public async Task<ProcessedData> ProcessEncryptedDataAsync(string encryptedData, string policyId)
    { 
       // Key Retrieval and Validation (using _kms and _securityPolicyManager)
       var key = await _kms.GetKeyAsync(policyId);
       if (!await _securityPolicyManager.ValidatePolicy(key, policyId)) {
           throw new SecurityException("Invalid or unauthorized key usage.");
       }

       // Decryption (using the retrieved key)
       var decryptedData =  EncryptDecryptUtility.Decrypt(encryptedData, key);

       // Route to Microservices (using _microserviceRegistry)
       var targetMicroservice = _microserviceRegistry.GetServiceByPolicyId(policyId);
       if (targetMicroservice == null) {
           throw new ServiceNotFoundException("No microservice found for the provided policy ID."); 
       }

       // Call Microservice and Handle Response
       var processedData = await targetMicroservice.ProcessDataAsync(decryptedData); 
       return processedData; 
    }
}



