void insertStringAfterOccurrence(std::forward_list<std::string>& list, const std::string& target, const std::string& insertion) {
    auto position = list.begin();
    while (position != list.end() && *position != target) {
        ++position;
    }

    if (position != list.end()) {
        list.insert_after(position, insertion);
    } else {
        list.push_back(insertion);
    }
}
