@app.route('/products/<int:product_id>')
def get_product(product_id):
    cached_product = redis_client.get(f'product:{product_id}') 
    if cached_product:
        return jsonify(json.loads(cached_product))

    # Fetch product data from external API or database
    product_data = get_product_from_api(product_id)  
    redis_client.set(f'product:{product_id}', json.dumps(product_data), ex=3600) # Cache for 1 hour
    return jsonify(product_data)

@celery.task()
def get_product_from_api(product_id):
    # Implement retry logic and circuit breaker here
    try:
        response = requests.get(f'https://api.example.com/products/{product_id}') 
        response.raise_for_status()  
        return response.json()

    except Exception as e:
        # Log error, implement fallback strategy, retry mechanism
        logging.error(f"Failed to retrieve product {product_id}: {e}") 
        return None



