pthread_cond_t eventsAvailable = PTHREAD_COND_INITIALIZER;

NetworkEvent* eventQueue; 
size_t queueSize;

void* eventProcessor(void* arg) {
    while (1) {
        pthread_mutex_lock(&eventMutex);
        while (queueSize == 0) {
            pthread_cond_wait(&eventsAvailable, &eventMutex);
        }
        NetworkEvent* event = eventQueue;
        eventQueue++;
        queueSize--;
        pthread_mutex_unlock(&eventMutex);

        // Process the event 
    }
    return NULL;
}


void addNetworkEvent(NetworkEvent event) {
    pthread_mutex_lock(&eventMutex);
    if (queueSize < MAX_QUEUE_SIZE) {
        memcpy(eventQueue, &event, sizeof(NetworkEvent));
        eventQueue++;
        queueSize++;
        pthread_cond_signal(&eventsAvailable);
    } else {
        // Handle queue overflow 
    }
    pthread_mutex_unlock(&eventMutex);
}

```



