public class Deserializer {

    private static final Logger LOGGER = LoggerFactory.getLogger(Deserializer.class);

    public <T> T deserialize(byte[] data, Class<T> clazz) {
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
            LOGGER.info("Deserializing object of type: {}", clazz.getName());
            T obj = (T) ois.readObject();
            LOGGER.info("Deserialization successful for class: {}", clazz.getName());
            return obj;
        } catch (IOException | ClassNotFoundException e) {
            LOGGER.error("Error deserializing object", e);
            throw new RuntimeException("Failed to deserialize object: " + e.getMessage(), e);
        } 
    }
}
