public class WeatherDataProcessor : IWeatherDataProvider
{
    private readonly List<IWeatherService> _weatherServices = new List<IWeatherService>();
    private readonly CacheManager _cacheManager; 

    // ... (Constructor and Methods for Weather Service Registration, Selection, Data Retrieval, etc.)

    public async Task<WeatherForecast> GetLatestForecast(string location)
    {
        var cachedData = _cacheManager.GetFromCache<WeatherForecast>(location);

        if (cachedData != null)
        {
            return cachedData;
        }

        foreach (var service in _weatherServices)
        {
            try
            {
                var forecast = await service.GetForecastAsync(location);
                _cacheManager.AddToCache(location, forecast);
                return forecast;
            }
            catch (Exception ex)
            {
                // Handle transient errors and retry with other services. Log the error.
                Console.WriteLine($"Error retrieving data from {service.Name}: {ex.Message}");
            }
        }

        // Handle scenarios where no valid data is retrieved. Return a default forecast or throw an exception.
        throw new Exception("No valid weather forecast found."); 
    }
}



