    int api_latency;
    int response_size;
    double error_rate;
} Context;

char* processString(const char* input, size_t size_limit, int trim, Context* context) {
  if (input == NULL || size_limit <= 0 || context == NULL) {
    return NULL; 
  }

  size_t input_length = strlen(input);

  if (input_length < size_limit) {
    char* processed_string = (char*)malloc(input_length + 2);
    strcpy(processed_string, input);
    processed_string[input_length] = 'X';
    processed_string[input_length + 1] = '\0';
    return processed_string;
  } else if (trim && input_length > size_limit) {
    char* processed_string = (char*)malloc(size_limit + 1);
    strncpy(processed_string, input, size_limit);
    processed_string[size_limit] = '\0';
    return processed_string;
  }

  return NULL; 
}


