class ScriptLoader {
    constructor() {
        this.loadedModules = {};
        this.loadingPromises = {};
    }

    async loadModule(moduleName) {
        if (this.loadedModules[moduleName]) {
            return Promise.resolve(this.loadedModules[moduleName]);
        }

        if (this.loadingPromises[moduleName]) {
            return this.loadingPromises[moduleName];
        }

        const promise = new Promise((resolve, reject) => {
            this.loadingPromises[moduleName] = promise;
            try {
                import(/* webpackChunkName: "module" */ `./${moduleName}`).then(module => {
                    this.loadedModules[moduleName] = module;
                    resolve(module);
                }).catch(error => {
                    reject(error);
                });
            } catch (error) {
                reject(error);
            }
        });

        return promise;
    }
    // ... add other methods for managing modules, error handling, context sharing etc.

}



