# Base Class JSONSerializable
class JSONSerializable:
    def to_json(self):
        raise NotImplementedError("Subclasses must implement to_json() method")

    @classmethod
    def from_json(cls, json_data):
        raise NotImplementedError("Subclasses must implement from_json() method")


# ClassRegistry for dynamic class registration
class ClassRegistry:
    def __init__(self):
        self._factory_map = {}
        self._lock = threading.Lock()

    def register_factory(self, identifier, factory_func):
        with self._lock:
            self._factory_map[identifier] = factory_func

    def unregister_factory(self, identifier):
        with self._lock:
            del self._factory_map[identifier]

    def get_factory(self, identifier):
        with self._lock:
            return self._factory_map.get(identifier)


# Example Subclass for JSONSerializable
class Person(JSONSerializable):
    def __init__(self, name, age):
        self.name = name
        self.age = age

    def to_json(self):
        return json.dumps({"name": self.name, "age": self.age})

    @classmethod
    def from_json(cls, json_data):
        data = json.loads(json_data)
        return cls(data["name"], data["age"])



```



