class MemoryManager {
public:
  MemoryManager(size_t capacity) : capacity_(capacity), allocatedSize_(0) {}

  void* allocate(size_t size) {
    if (allocatedSize_ + size > capacity_) {
      // Handle memory overflow, e.g., resize or throw an exception
      return nullptr; 
    }
    void* ptr = static_cast<void*>(memory_ + allocatedSize_);
    allocatedSize_ += size;
    return ptr;
  }

  double calculateAverage(const std::vector<CustomData>& data) {
    int sum = 0;
    for (const auto& item : data) {
      sum += item.field1 + item.field2;
    }
    return static_cast<double>(sum) / data.size();
  }

private:
  size_t capacity_;
  size_t allocatedSize_;
  char* memory_; // Assuming a contiguous memory block
};

