    void addConnectionUpdate(const ConnectionStatusUpdate& update) {
        std::lock_guard<std::mutex> lock(connectionUpdatesMutex_);
        connectionUpdates_.push(update);
        cv_.notify_one(); // Notify workers about new updates
    }

    void startWorkers() {
        for (int i = 0; i < workerThreads_; ++i) {
            workers_.emplace_back(&ConnectionStatusManager::processUpdates, this);
        }
    }

