bool cooldown_active = false;
std::chrono::system_clock::time_point last_attack_time;

void selectAttack() {
  if (cooldown_active) {
    auto current_time = std::chrono::system_clock::now();
    auto elapsed_seconds = std::chrono::duration<double>(current_time - last_attack_time).count();

    if (elapsed_seconds >= 9.0) { 
      cooldown_active = false;
      last_attack_time = current_time;
    }
    return; 
  }

  std::random_device rd;  
  std::mt19937 gen(rd());  
  std::uniform_int_distribution<> distrib(0, 1); 

  int attackChoice = distrib(gen);

  if (attackChoice == 0) {
    // Perform Attack 1 implementation
    std::cout << "Character used Attack 1\n";
  } else {
    // Perform Attack 2 implementation
    std::cout << "Character used Attack 2\n";
  }

  cooldown_active = true;
  last_attack_time = std::chrono::system_clock::now();
}
