    """
    Calculates the SHA-256 hash of a file.
    """
    with open(file_path, 'rb') as f:
        # ... (Asynchronous I/O and memory mapping optimization) ...

        hasher = hashlib.sha256()
        while True:
            chunk = f.read(chunk_size)
            if not chunk:
                break
            hasher.update(chunk)

    return hasher.hexdigest()

