int loadResourceBundle(const char* path) {
  FILE* file = fopen(path, "r");
  if (file == nullptr) {
    return -1;
  }
  fseek(file, 0, SEEK_END);
  long size = ftell(file);
  rewind(file);

  char* buffer = new char[size + 1];
  size_t bytesRead = fread(buffer, sizeof(char), size, file);
  if (bytesRead != size) {
    delete[] buffer;
    return -2;
  }
  buffer[size] = '\0';

  fclose(file);

  // Process the buffer to count items...

  delete[] buffer;
  return itemCount; 
}
