import java.util.*;

public class DisjointPairsCounter {

    private int[] parent;
    private int[] rank;

    public DisjointPairsCounter(int n) {
        parent = new int[n];
        rank = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    public int find(int u) {
        if (parent[u] != u) {
            parent[u] = find(parent[u]); // Path compression
        }
        return parent[u];
    }

    public void union(int u, int v) {
        int rootU = find(u);
        int rootV = find(v);
        if (rootU != rootV) {
            if (rank[rootU] < rank[rootV]) {
                parent[rootU] = rootV;
            } else if (rank[rootU] > rank[rootV]) {
                parent[rootV] = rootU;
            } else {
                parent[rootV] = rootU;
                rank[rootU]++;
            }
        }
    }

    public int countDisjointPairs(int[] arr) {
        long startTime = System.currentTimeMillis();
        Set<Integer> seen = new HashSet<>();
        int count = 0;
        for (int i = 0; i < arr.length; i++) {
            if (!seen.contains(arr[i])) {
                seen.add(arr[i]);
                for (int j = i + 1; j < arr.length; j++) {
                    if (!seen.contains(arr[j])) {
                        union(arr[i], arr[j]);
                        count++;
                    }
                }
            }
        }
        long endTime = System.currentTimeMillis();
        System.out.println("Time taken: " + (endTime - startTime) + " milliseconds");
        return count;
    }

    public static void main(String[] args) {
        int[] arr = {1, 2, 3, 4, 5, 6, 7, 8, 9};
        DisjointPairsCounter counter = new DisjointPairsCounter(10); // Assuming maximum element value is 9
        int count = counter.countDisjointPairs(arr);
        System.out.println("Number of disjoint pairs: " + count);
    }
}
