public class RemoteDataProcessor {

    private final Map<String, DataConnection> connections = new HashMap<>();
    private final Queue<DataProcessingTask> taskQueue = new LinkedList<>();
    private final ExecutorService executor = Executors.newFixedThreadPool(10); // Adjust thread pool size as needed

    public void processTask(DataProcessingTask task) {
        taskQueue.add(task);
    }

    public void start() {
        executor.execute(this::processTasks);
    }

    private void processTasks() {
        while (true) {
            DataProcessingTask task = taskQueue.poll();
            if (task == null) {
                break;
            }

            String sourceId = task.getContext().getSourceId();
            DataConnection connection = connections.computeIfAbsent(sourceId, key -> new DataConnection(key)); 
