#include <map>
#include <queue>
#include <chrono>

class AttackCooldown {
public:
    struct AttackInfo {
        std::string name;
        int cooldownDuration; // In milliseconds
    };

    AttackCooldown() {}

    void RegisterAttack(const std::string& name, int cooldownDuration) {
        attackData[name] = cooldownDuration;
    }

    bool IsReadyToAttack(const std::string& name) const {
        auto it = attackData.find(name);
        if (it == attackData.end()) {
            return true; // Attack not registered
        }

        auto& cooldownTime = it->second;
        auto now = std::chrono::high_resolution_clock::now();
        if (lastAttackTime[name] + std::chrono::milliseconds(cooldownTime) < now) {
            return true; 
        }
        return false;
    }

    void AttackUsed(const std::string& name) {
        lastAttackTime[name] = std::chrono::high_resolution_clock::now();
    }

private:
    std::map<std::string, int> attackData; // Name -> Cooldown duration
    std::map<std::string, std::chrono::system_clock::time_point> lastAttackTime; 
};
```


