# DynamicStreamProcessor library skeleton - This is NOT production ready code

from abc import ABC, abstractmethod
import threading
import queue
import time 


class DataSink(ABC):
    @abstractmethod
    def process_data(self, data):
        pass

class DataSource(ABC):
    @abstractmethod
    def read_data(self) -> dict:
        pass

class StreamProcessor(threading.Thread):
    def __init__(self, source: DataSource, sink: DataSink, buffer_size=1024):
        super().__init__()
        self.source = source
        self.sink = sink
        self.buffer = queue.Queue(maxsize=buffer_size)

    def run(self):
        while True:
            data = self.source.read_data() 
            self.buffer.put(data) 
            # Process data from buffer periodically (consider a separate thread for processing)

class DynamicStreamProcessor:
    def __init__(self):
        self.processors = {}  

    def add_pipeline(self, name: str, source: DataSource, sink: DataSink):
        processor = StreamProcessor(source, sink) 
        self.processors[name] = processor
        processor.start()

