// This code snippet is a simplified representation 
// and does not cover the full complexity of the framework.

#include <iostream>
#include <thread>
#include <queue>
#include <mutex>
#include <condition_variable>

class Task {
public:
    Task(const std::string& name) : name(name) {}
    std::string name;
};

class TaskQueue {
private:
    std::queue<Task*> tasks;
    std::mutex mutex_;
    std::condition_variable cv_;

public:
    void enqueue(Task* task) {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            tasks.push(task);
        }
        cv_.notify_one(); // Notify a worker thread
    }

    Task* dequeue() {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this]{ return !tasks.empty(); }); 
        Task* task = tasks.front();
        tasks.pop();
        return task;
    }
};

void workerThread(TaskQueue& queue) {
    while (true) {
        Task* task = queue.dequeue();
        std::cout << "Processing task: " << task->name << std::endl; 
        // Simulate processing time
        std::this_thread::sleep_for(std::chrono::milliseconds(100)); 
    }
}

int main() {
    TaskQueue queue;
    std::thread worker1(workerThread, std::ref(queue));
    std::thread worker2(workerThread, std::ref(queue));

    queue.enqueue(new Task("Task 1"));
    queue.enqueue(new Task("Task 2"));

    worker1.join();
    worker2.join();
    return 0;
}

```



**Explanation:**

* This code provides a basic structure for a task queue with worker threads. It demonstrates the core concepts of:
    *  **Task Representation:** `Task` class holds the task's name (you would add more fields as needed).
