class ConnectionStatusCache {
 public:
  ConnectionStatusCache(int nRecords, int maxRecords) : 
      nRecords_(nRecords), maxRecords_(maxRecords) {}

  // Add a connection status update (asynchronously)
  void AddUpdate(const std::string& key, bool status) {
    std::lock_guard<std::mutex> lock(mutex_);
    updates_.push({key, status});
    cv_.notify_one(); 
  }

  // Read the connection status for a given key
  bool GetStatus(const std::string& key) {
    std::lock_guard<std::mutex> lock(mutex_);
    auto it = cache_.find(key);
    return it != cache_.end() ? it->second : false; 
  }

 private:
  void ProcessUpdates() {
    while (true) {
      std::unique_lock<std::mutex> lock(mutex_);
      cv_.wait(lock, [this] { return !updates_.empty(); });

      // Process updates in batches to minimize contention
      for (auto& update : updates_) {
        cache_[update.key] = update.status; 
      }
      updates_.clear();

      // Additional processing for write operations and consistency
    }
  }

  int nRecords_;
  int maxRecords_;
  std::map<std::string, bool> cache_; 
  std::queue<std::pair<std::string, bool>> updates_; 
  std::mutex mutex_;
  std::condition_variable cv_;
};


