typedef struct {
    // ... fields of NFAPI_CRC_INDICATION_PDU_T ...
} NFAPI_CRC_INDICATION_PDU_T;

// Define the linked list node structure
typedef struct LinkedListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct LinkedListNode *next;
} LinkedListNode;

// Global linked list pointer and mutex for thread safety
LinkedListNode *head = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to insert a new node at the end of the list
void insert_node(NFAPI_CRC_INDICATION_PDU_T *data) {
    LinkedListNode *new_node = malloc(sizeof(LinkedListNode));
    new_node->data = *data;
    new_node->next = NULL;

    pthread_mutex_lock(&list_mutex);
    if (head == NULL) {
        head = new_node;
    } else {
        LinkedListNode *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&list_mutex);
}

// Function to delete a node with a given RX_UE_INFORMATION_TAG and RNTI
void delete_node(uint32_t rx_ue_info, uint16_t rnti) {
    pthread_mutex_lock(&list_mutex);
    LinkedListNode *current = head;
    LinkedListNode *previous = NULL;

    while (current != NULL) {
        if (current->data.rx_ue_info == rx_ue_info && current->data.rnti == rnti) {
            if (previous == NULL) {
                head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list_mutex);
}

// Function to traverse and print the linked list
void print_list() {
    LinkedListNode *current = head;
    while (current != NULL) {
        printf("RX_UE_INFO: %u, RNTI: %u\n", current->data.rx_ue_info, current->data.rnti);
        current = current->next;
    }
}

