char* truncate_string(const char *str, int size_limit) {
  if (strlen(str) > size_limit) {
    return NULL;
  } else {
    char *new_str = malloc(size_limit + 2);
    strcpy(new_str, str);
    new_str[size_limit] = '/';
    new_str[size_limit + 1] = '\0';
    return new_str;
