public DataTableReader SendBytesToDatabaseAndQuery(byte[] byteArray)
{
  // Database connection string and query parameters
  string connectionString = "YourConnectionString"; 
  string query = "INSERT INTO YourTable (DataBlob) VALUES (@Data)";

  using (SqlConnection connection = new SqlConnection(connectionString))
  {
    SqlCommand command = new SqlCommand(query, connection);
    command.Parameters.AddWithValue("@Data", byteArray);

    connection.Open();
    command.ExecuteNonQuery();

    // Execute the read query using a DataTableReader
    string selectQuery = "SELECT * FROM YourTable";
    SqlDataAdapter adapter = new SqlDataAdapter(selectQuery, connection);
    DataTable table = new DataTable();
    adapter.Fill(table);
    return table.CreateDataReader(); 
  }
}
