public class CacheItemManager {

    private final Map<String, CacheItem> cache = new ConcurrentHashMap<>();
    private final MessageBroker messageBroker;
    private final DistributedLogger logger;

    public CacheItemManager(MessageBroker messageBroker, DistributedLogger logger) {
        this.messageBroker = messageBroker;
        this.logger = logger;
    }

    public void addItem(Map<String, Object> itemData, boolean isVolatile) {
        CacheItem item = new CacheItem(itemData);
        if (isVolatile) {
            item.setExpirationTimestamp(System.currentTimeMillis() + itemData.get("ttl")); 
        } else {
            item.removeExpirationTimestamp();
        }

        cache.putIfAbsent(item.getKey(), item);
        messageBroker.publishUpdate(item);
    }

    // Other methods for update, delete, query, etc. ...
}


