class APIHandler {
public:
    virtual ~APIHandler() = default;
    virtual std::string fetchData(const std::string& endpoint) = 0;
};

template <typename T>
class CachedData {
private:
    std::mutex mutex_;
    std::condition_variable cv_;
    T data_;
    std::chrono::system_clock::time_point lastUpdated_;

public:
    void set(const T& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        data_ = value;
        lastUpdated_ = std::chrono::system_clock::now();
        cv_.notify_all(); 
    }

    T get() const {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait_until(lock, lastUpdated_ + std::chrono::minutes(5), []{ return true; }); // Adjust cache timeout as needed
        return data_;
    }
};

class CommandLineTool {
private:
    APIHandler* apiHandler;  // Choose a concrete APIHandler implementation
    std::shared_ptr<CachedData<int>> cachedData; 

