#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct Node {
    int data;
    struct Node *left;
    struct Node *right;
} Node;

typedef struct DoublyLinkedListNode {
    Node *node;
    struct DoublyLinkedListNode *prev;
    struct DoublyLinkedListNode *next;
} DoublyLinkedListNode;

typedef struct DoublyLinkedList {
    DoublyLinkedListNode *head;
    DoublyLinkedListNode *tail;
} DoublyLinkedList;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void breadthFirstTraversal(Node *root, int maxDepth, void (*treeOp)(Node*)) {
    DoublyLinkedList queue;
    queue.head = NULL;
    queue.tail = NULL;

    if (root == NULL) {
        return;
    }

    DoublyLinkedListNode *newNode = malloc(sizeof(DoublyLinkedListNode));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newNode->node = root;
    newNode->prev = NULL;
    newNode->next = NULL;

    if (queue.head == NULL) {
        queue.head = newNode;
        queue.tail = newNode;
    } else {
        queue.tail->next = newNode;
        newNode->prev = queue.tail;
        queue.tail = newNode;
    }

    int currentDepth = 1;

    while (currentDepth <= maxDepth && queue.head != NULL) {
        DoublyLinkedListNode *currentNode = queue.head;
        while (currentNode != NULL) {
            treeOp(currentNode->node);
            if (currentNode->node->left != NULL) {
                pthread_mutex_lock(&mutex);
                newNode = malloc(sizeof(DoublyLinkedListNode));
                if (newNode == NULL) {
                    fprintf(stderr, "Memory allocation failed\n");
                    exit(1);
                }
                newNode->node = currentNode->node->left;
                newNode->prev = NULL;
                newNode->next = NULL;

                if (queue.head == NULL) {
                    queue.head = newNode;
                    queue.tail = newNode;
                } else {
                    queue.tail->next = newNode;
                    newNode->prev = queue.tail;
                    queue.tail = newNode;
                }
                pthread_mutex_unlock(&mutex);
            }

            if (currentNode->node->right != NULL) {
                pthread_mutex_lock(&mutex);
                newNode = malloc(sizeof(DoublyLinkedListNode));
                if (newNode == NULL) {
                    fprintf(stderr, "Memory allocation failed\n");
                    exit(1);
                }
                newNode->node = currentNode->node->right;
                newNode->prev = NULL;
                newNode->next = NULL;

                if (queue.head == NULL) {
                    queue.head = newNode;
                    queue.tail = newNode;
                } else {
                    queue.tail->next = newNode;
                    newNode->prev = queue.tail;
                    queue.tail = newNode;
                }
                pthread_mutex_unlock(&mutex);
            }

            currentNode = currentNode->next;
        }
        currentDepth++;
    }
}

