#include <boost/asio.hpp>
#include <boost/thread.hpp>

class ProxyServer {
 public:
  ProxyServer(const std::string& address, int port) : io_context(), acceptor_(io_context, boost::asio::ip::tcp::endpoint(boost::asio::ip::tcp::v4(), port)) {}

  void start() {
    doAccept();
  }

 private:
  void doAccept() {
    acceptor_.async_accept([this](boost::system::error_code ec, boost::asio::ip::tcp::socket socket) {
      if (!ec) {
        std::make_shared<ClientSession>(std::move(socket))->start();
      }
      doAccept();
    });
  }

  boost::asio::io_context io_context;
  boost::asio::ip::tcp::acceptor acceptor_;
};

class ClientSession {
 public:
  ClientSession(boost::asio::ip::tcp::socket socket) : socket_(std::move(socket)) {}

  void start() {
    doRead();
  }

 private:
  void doRead() {
    auto self = shared_from_this();
    socket_.async_read_some(boost::asio::buffer(data_), [self](boost::system::error_code ec, std::size_t length) {
      if (!ec) {
        // Process received data
      } else {
        // Handle error
      }
      doRead();
    });
  }

  boost::asio::ip::tcp::socket socket_;
  std::array<char, 1024> data_;
};


int main() {
  ProxyServer server("localhost", 8080);
  server.start();

  // Run the event loop
  server.io_context.run();

  return 0;
}
