async void asynchronousAggregator(const std::vector<NFAPI_CRC_INDICATION_PDU_T>& data) {
  std::mutex dbMutex;
  std::condition_variable cv;
  std::queue<NFAPI_CRC_INDICATION_PDU_T> processedData;

  auto processBatch = [&](const std::vector<NFAPI_CRC_INDICATION_PDU_T>& batch) {
    for (const auto& element : batch) {
      // Process each element with third-party services and database interactions
      // ...
      std::unique_lock<std::mutex> lock(dbMutex);
      processedData.push(element); // Add processed element to queue
      cv.notify_one();
    }
  };

  std::vector<std::future<void>> futures;
  for (size_t i = 0; i < data.size(); i += 1000) { // Batch processing example
    futures.push_back(std::async(processBatch, std::vector<NFAPI_CRC_INDICATION_PDU_T>(data.begin() + i, data.begin() + std::min(i + 1000, data.size()))));
  }

  for (auto& future : futures) {
    future.wait(); // Wait for all batch processing to complete
  }

  // Process remaining elements in queue
  while (!processedData.empty()) {
    // ... handle processed data from the queue ...
  }
}
