#include <atomic>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <thread>

// Placeholder for external dependencies 
class EventProcessor {
public:
    virtual void processEvent(const std::shared_ptr<Event>& event) = 0;
};

class CloudStorageService {
public:
    virtual bool uploadEvent(const std::shared_ptr<Event>& event) = 0;
};


template <typename EventProcessor, typename CloudStorage>
class EventManager {
private:
    std::atomic<bool> running_;
    std::mutex queueMutex_;
    std::condition_variable eventCV_;
    std::queue<std::shared_ptr<Event>> eventQueue_; 

    EventProcessor& processor_;
    CloudStorage& storage_;

public:
    EventManager(EventProcessor& processor, CloudStorage& storage)
        : running_(true), processor_(processor), storage_(storage) {}

    void addEvent(const std::shared_ptr<Event>& event) {
        std::unique_lock<std::mutex> lock(queueMutex_);
        eventQueue_.push(event);
        eventCV_.notify_one();
    }

    void processEvents() {
        while (running_) {
            std::unique_lock<std::mutex> lock(queueMutex_);
            eventCV_.wait(lock, [this] { return !eventQueue_.empty() || !running_; });
            if (!running_) { break; }

            auto event = eventQueue_.front();
            eventQueue_.pop();
            lock.unlock();

            processor_.processEvent(event); // Assuming EventProcessor handles async processing
            storage_.uploadEvent(event);  // Assuming CloudStorage handles async storage
        }
    }

    void stop() {
        running_ = false;
        eventCV_.notify_all();
    }
};



``` 


