namespace Base64DecryptModule
{
    public class MoSTStateDecrypter
    {
        private readonly string _jsonPath = "most_state.json"; // Default JSON file path
        private static object _lockObject = new object();
        private MoSTState _cachedMoSTState;

        public string DecryptMessage(string base64EncryptedText, string key, string iv)
        {
            byte[] decodedBytes = Convert.FromBase64String(base64EncryptedText);
            using (TripleDESCryptoServiceProvider tdes = new TripleDESCryptoServiceProvider())
            {
                tdes.Key = ASCIIEncoding.ASCII.GetBytes(key);
                tdes.IV = ASCIIEncoding.ASCII.GetBytes(iv);

                try
                {
                    byte[] decryptedBytes = tdes.Decrypt(decodedBytes, true);
                    return DeserializeMoSTState(decryptedBytes);
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Decryption Error: {ex.Message}"); 
                    throw; // Re-throw for handling at a higher level
                }
            }
        }

        private string DeserializeMoSTState(byte[] decryptedBytes)
        {
            lock (_lockObject)
            {
                if (_cachedMoSTState != null && DateTime.Now - _cachedMoSTState.LastUpdated < TimeSpan.FromMinutes(5)) // Check cache validity
                {
                    return _cachedMoSTState.ToString(); 
                }

                string jsonString = Encoding.UTF8.GetString(decryptedBytes);
                try
                {
                    _cachedMoSTState = JsonConvert.DeserializeObject<MoSTState>(jsonString); 
                    _cachedMoSTState.LastUpdated = DateTime.Now;
                    return _cachedMoSTState.ToString(); 
                }
                catch (JsonException ex)
                {
                    Console.WriteLine($"JSON Deserialization Error: {ex.Message}");
                    return "Invalid JSON format"; // Handle gracefully
                }
            }
        }

        // ... Add methods for setting dynamic JSON file paths, logging, etc.
    }
}
