public class LogProcessor
{
    private readonly ILogParserFactory _logParserFactory;
    private readonly IMonitoringSystemIntegrator _monitoringSystemIntegrator;

    public LogProcessor(ILogParserFactory logParserFactory, IMonitoringSystemIntegrator monitoringSystemIntegrator)
    {
        _logParserFactory = logParserFactory;
        _monitoringSystemIntegrator = monitoringSystemIntegrator;
    }

    public async Task ProcessLogStreamAsync(Stream logStream)
    {
        using (var reader = new StreamReader(logStream))
        {
            while (!reader.EndOfStream)
            {
                var logEntry = await reader.ReadLineAsync();
                var parser = _logParserFactory.CreateParser(logEntry);
                var parsedData = parser.Parse(logEntry);

                // Aggregate metrics and send to monitoring system
                _monitoringSystemIntegrator.SendMetrics(parsedData);
            }
        }
    }
}
